open(lib,'w').write('''"""Reusable grid functions for ARC-style tasks."""
from collections import Counter

def side_neighbors(i, j, h, w):
    """The in-bounds 4-side neighbors of cell (i, j)."""
    return [(x, y) for x, y in [(i-1, j), (i+1, j), (i, j-1), (i, j+1)] if 0 <= x < h and 0 <= y < w]

def noise_cells(grid):
    """Cells differing from all their 4-side neighbors (isolated stray pixels)."""
    h, w = len(grid), len(grid[0])
    return {(i, j) for i in range(h) for j in range(w)
            if all(grid[x][y] != grid[i][j] for x, y in side_neighbors(i, j, h, w))}

def uniform_rectangles(grid, holes=frozenset()):
    """Maximal uniform color rectangles with both sides >= 2; holes (e.g. noise cells) allowed. Each is (color, top, left, height, width)."""
    h, w = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    rects = []
    for c in cnt:
        for r1 in range(h):
            for c1 in range(w):
                if grid[r1][c1] != c and (r1, c1) not in holes:
                    continue
                for hh in range(2, h - r1 + 1):
                    ww = 2
                    while ww <= w - c1:
                        if not all(grid[a][b] == c or (a, b) in holes for a in range(r1, r1 + hh) for b in range(c1, c1 + ww)):
                            break
                        up = r1 > 0 and all(grid[r1-1][b] == c or (r1-1, b) in holes for b in range(c1, c1 + ww))
                        dn = r1 + hh < h and all(grid[r1+hh][b] == c or (r1+hh, b) in holes for b in range(c1, c1 + ww))
                        lf = c1 > 0 and all(grid[a][c1-1] == c or (a, c1-1) in holes for a in range(r1, r1 + hh))
                        rt = c1 + ww < w and all(grid[a][c1+ww] == c or (a, c1+ww) in holes for a in range(r1, r1 + hh))
                        if not (up or dn or lf or rt):
                            rects.append((c, r1, c1, hh, ww))
                        ww += 1
    return list({r for r in rects})

def background_color(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def denoise(grid):
    """Replace each isolated stray pixel by the color of the uniform rectangle containing it (non-background preferred, smallest first), else the background color."""
    h, w = len(grid), len(grid[0])
    bg = background_color(grid)
    noise = noise_cells(grid)
    rects = uniform_rectangles(grid, holes=noise)
    out = [row[:] for row in grid]
    for i, j in noise:
        ins = [(c, hh * ww) for c, r1, c1, hh, ww in rects if r1 <= i < r1 + hh and c1 <= j < c1 + ww]
        if ins:
            pref = [x for x in ins if x[0] != bg] or ins
            pref.sort(key=lambda x: x[1])
            out[i][j] = pref[0][0]
        else:
            out[i][j] = bg
    return out
''')
